elements.variants_sample:
HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("filled"); Text("filled").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("tonal"); Text("tonal").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("outlined"); Text("outlined").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("text"); Text("text").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Button("Label").variant("elevated"); Text("elevated").font(.caption).foregroundStyle(.secondary) }
}

HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { Card("Title") { Text("Content"); Button("Action") }.variant("filled"); Text("filled").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Card("Title") { Text("Content"); Button("Action") }.variant("elevated"); Text("elevated").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { Card("Title") { Text("Content"); Button("Action") }.variant("outlined"); Text("outlined").font(.caption).foregroundStyle(.secondary) }
}

HStack(alignment: .top, spacing: 24) {
  VStack(alignment: .leading, spacing: 4) { TextField("Label").variant("filled"); Text("filled").font(.caption).foregroundStyle(.secondary) }
  VStack(alignment: .leading, spacing: 4) { TextField("Label").variant("outlined"); Text("outlined").font(.caption).foregroundStyle(.secondary) }
}

